contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking an amount to forward to c.go
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // read owner before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // attempt the call and record whether it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read owner after
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General invariant: owner never changes regardless of success or revert
        assert(ownerAfter == ownerBefore);
    }

    // allow receiving Ether so this contract can fund c.go
    receive() external payable {}
}

